package main

import (
	"math/rand"
	"testing"
)

func eqCert(a, b Certificate) bool {
	return a.Kind == b.Kind && a.Edge == b.Edge
}

func TestBasic(t *testing.T) {
	// Path 1-2-3-4-5 with weights 5,3,7,3 (edges 1..4).
	n := 5
	eu := []int{0, 1, 2, 3, 4}
	ev := []int{0, 2, 3, 4, 5}
	ew := []int64{0, 5, 3, 7, 3}
	tr := NewTree(n, eu, ev, ew)

	if c := tr.Query(1, 5, 10); c.Kind != CertSingle || c.Edge != 1 {
		t.Fatalf("q(1,5,10)=%+v want single 1", c)
	}
	if c := tr.Query(1, 5, 6); c.Kind != CertEmpty {
		t.Fatalf("q(1,5,6)=%+v want empty", c)
	}
	if c := tr.Query(1, 5, 8); c.Kind != CertSingle || c.Edge != 1 {
		t.Fatalf("q(1,5,8)=%+v want single 1", c)
	}
	if c := tr.Query(2, 3, 4); c.Kind != CertSingle || c.Edge != 2 {
		t.Fatalf("q(2,3,4)=%+v want single 2", c)
	}
	if c := tr.Query(1, 3, 4); c.Kind != CertEmpty {
		t.Fatalf("q(1,3,4)=%+v want empty", c)
	}
	if c := tr.Query(1, 3, 6); c.Kind != CertSingle || c.Edge != 1 {
		t.Fatalf("q(1,3,6)=%+v want single 1", c)
	}
	if c := tr.Query(4, 5, 4); c.Kind != CertSingle || c.Edge != 4 {
		t.Fatalf("q(4,5,4)=%+v want single 4", c)
	}
	if c := tr.Query(3, 3, 100); c.Kind != CertNone {
		t.Fatalf("q(3,3)=%+v want none", c)
	}
	if c := tr.Query(1, 2, 5); c.Kind != CertEmpty {
		t.Fatalf("q(1,2,5)=%+v want empty (strict <)", c)
	}
	if c := tr.Query(1, 2, 6); c.Kind != CertSingle || c.Edge != 1 {
		t.Fatalf("q(1,2,6)=%+v want single 1", c)
	}
}

func TestUpdateAndRepeatedUpdates(t *testing.T) {
	n := 5
	eu := []int{0, 1, 2, 3, 4}
	ev := []int{0, 2, 3, 4, 5}
	ew := []int64{0, 5, 3, 7, 3}
	tr := NewTree(n, eu, ev, ew)

