	tr.UpdateWeight(3, 2)
	tr.UpdateWeight(3, 2)
	if c := tr.Query(1, 5, 6); c.Kind != CertSingle || c.Edge != 1 {
		t.Fatalf("repeated update q(1,5,6)=%+v want single 1", c)
