func randTree(rng *rand.Rand, n int, maxW int64) ([]int, []int, []int64) {
	eu := make([]int, n)
	ev := make([]int, n)
	ew := make([]int64, n)
	for v := 2; v <= n; v++ {
		p := rng.Intn(v-1) + 1
		eu[v-1] = p
		ev[v-1] = v
		ew[v-1] = int64(rng.Intn(int(maxW)) + 1)
	}
	return eu, ev, ew
}

